contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address logger, address other, bool status) public {
        // Set the approval status for logger to status (true or false)
        c.setApprovedLogger(logger, status);
        // Read back the approval status for logger
        bool approvedLogger = c.approvedToLog(logger);
        // Also read the approval status for another address to ensure separation
        bool approvedOther = c.approvedToLog(other);
        // The general rule: approvedToLog returns exactly the value that was set,
        // and other addresses remain unaffected (false unless previously set).
        // We only assert on logger's status to avoid dependence on other's initial state.
        assert(approvedLogger == status);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address logger, address other, bool status) public {
        require(logger != other, "logger and other must be distinct");
        require(other != address(0), "other must not be zero address");

        // Read the initial status of 'other' before any state change
        bool otherBefore = c.approvedToLog(other);

        // Set the approval status for 'logger' to 'status'
        c.setApprovedLogger(logger, status);

        // Read the approval status for 'logger' and 'other' after the state change
        bool loggerAfter = c.approvedToLog(logger);
        bool otherAfter = c.approvedToLog(other);

        // General rule: the setter works exactly as a boolean assignment for the given logger,
        // and leaves unrelated addresses untouched. Since 'other' is never set (distinct from logger),
        // its status before and after must be equal.
        assert(loggerAfter == status && otherBefore == otherAfter);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address logger, address other, bool status) public {
        // No preconditions on c's state: the contract starts fresh.
        // Snapshot other's status before the setter call (no assumption about its value).
        bool otherBefore = c.approvedToLog(other);

        // Top-level state-changing call: set logger's approval to `status`.
        c.setApprovedLogger(logger, status);

        // Read back the new statuses.
        bool loggerAfter = c.approvedToLog(logger);
        bool otherAfter = c.approvedToLog(other);

        // General rule: the setter acts as a boolean assignment for the exact
        // target address. For any address different from `logger` whose status
        // was not changed by this call, the flag is preserved. Since `other`
        // was observed before any state change, for `other != logger` the flag
        // before and after must be equal.
        assert(loggerAfter == status && (other == logger || otherAfter == otherBefore));
    }

    receive() external payable {}
}

