contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address logger, address caller, bool status) public {
        require(logger != caller, "caller must differ");

        c.setApprovedLogger(logger, true);

        bool loggerApproved = c.approvedToLog(logger);
        bool callerApproved = c.approvedToLog(caller);

        bool reverted;
        bool returned;
        if (caller == logger) {
            returned = c.logCreated(address(0));
        } else {
            try c.logCreated(address(0)) returns (bool r) {
                returned = r;
            } catch {
                reverted = true;
            }
        }

        assert(
            (caller == logger)
                ? (loggerApproved && !reverted && returned)
                : (!callerApproved && reverted)
        );
    }

    receive() external payable {}
}

