    }

    function run(address logger, bool status) public {
        require(logger != address(0));

        bool before = c.approvedToLog(logger);

        bool reverted;
        try c.setApprovedLogger(logger, status) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool after = c.approvedToLog(logger);

        assert(
            (reverted && after == before) ||
            (!reverted && after == status)
        );
